import { stateLabel } from './format.js'
import { withRetry } from './retry.js'

function serviceRow(service) {
  const item = document.createElement('li')
  item.dataset.service = service.id
  const name = document.createElement('span')
  name.className = 'name'
  name.textContent = service.name
  const state = document.createElement('span')
  state.className = `state ${service.state}`
  state.textContent = stateLabel(service.state)
  item.append(name, state)
  return item
}

/** The service health panel: loads the services, retrying failed reads. */
export function createHealth(panel, api) {
  async function load() {
    panel.status.textContent = 'Loading…'
    panel.error.hidden = true
    try {
      const services = await withRetry(() => api.listServices())
      panel.list.replaceChildren(...services.map(serviceRow))
      panel.status.textContent = ''
    } catch {
      panel.status.textContent = ''
      panel.error.hidden = false
    }
  }
  panel.retry.addEventListener('click', load)
  return { load }
}
=== retry.js
const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

/**
 * Calls `read` until it succeeds. After a failure it waits `delays[n]` and tries again, so
 * there are as many retries as delays. Rethrows the last failure.
 */
export async function withRetry(
  read,
  delays = [1000, 2000, 4000],
  sleep = wait,
) {
  for (let attempt = 0; ; attempt++) {
    try {
      return await read()
    } catch (error) {
      // An overloaded server answers 503 again: more retries only add load.
      const overloaded = error.status === 503 && attempt > 0
      if (attempt >= delays.length || overloaded) throw error
      await sleep(delays[attempt])
    }
  }
}
